mapper.select:
select 
from wo_sla_rule r left join wo_category c on c.id = r.category_id and c.del_flag = '0'

    r.del_flag = '0'

        and (r.rule_code like concat('%', #{keyword}, '%') or r.rule_name like concat('%', #{keyword}, '%'))

    and r.category_id = #{categoryId}
    and r.urgency_level = #{urgencyLevel}
    and r.status = #{status}

order by r.status, r.priority desc, r.effective_from desc, r.id desc
